function sumKey(ds, key) {
  return ((ds && ds.rows) || []).reduce((a, r) => a + (Number(r[key]) || 0), 0);
}
function rowBy(ds, label) {
  return ((ds && ds.rows) || []).find((r) => r.date === label) || {};
}
function gm(b, pics, ph, pc, u) {
  const cost = b.textCost + b.narration + pics * b.picPrice;
  const rev = b.custH * ph + b.custC * pc;
  const stories = (b.custH * b.incH + b.custC * b.incC) * u;
  const fixed = b.hosting + b.bill;
  return rev > 0 ? (rev - fixed - stories * cost) / rev : 0;
}
function Block({ data, state, emit }) {
  const [phS, setPh] = React.useState(null);
  const [pcS, setPc] = React.useState(null);
  const [picS, setPic] = React.useState(null);
  const [uS, setU] = React.useState(null);
  const bad = ['customers', 'plan', 'verif', 'illus', 'cost', 'scalars', 'bill'].find((k) => !data[k] || data[k].error);
  if (bad) return <Text variant="soft">Dataset {bad} is unavailable.</Text>;
  const cr = (data.customers.rows || [])[0] || {};
  const h = rowBy(data.plan, 'Household');
  const c = rowBy(data.plan, 'Classroom');
  const sc = (data.scalars.rows || [])[0] || {};
  const pp = rowBy(data.cost, 'Picture price each');
  const np = rowBy(data.cost, 'Narration price per page');
  const pg = rowBy(data.cost, 'Pages per story');
  const b = {
    custH: Number(cr['Household']) || 0,
    custC: Number(cr['Classroom']) || 0,
    incH: Number(h['Stories included per month (assumed)']) || 0,
    incC: Number(c['Stories included per month (assumed)']) || 0,
    picPrice: Number(pp['Cost input value']) || 0,
    narration: (Number(np['Cost input value']) || 0) * (Number(pg['Cost input value']) || 0),
    textCost: sumKey(data.verif, 'Selected text and verification cost (USD, derived)'),
    hosting: Number(sc['Hosting per month (USD, assumed)']) || 0,
    bar: Number(sc['Gross margin bar (ours, stated)']) || 0,
    bill: sumKey(data.bill, 'neatlogs bill (USD, derived)'),
  };
  const baseH = Number(h['Price per month (USD, assumed)']) || 0;
  const baseC = Number(c['Price per month (USD, assumed)']) || 0;
  const baseU = b.incH > 0 ? (Number(h['Stories used per customer (derived)']) || 0) / b.incH : 0;
  const picNarr = sumKey(data.illus, 'Selected picture and narration cost (USD, derived)');
  const basePics = b.picPrice > 0 ? Math.round((picNarr - b.narration) / b.picPrice) : 0;
  const ph = phS ?? baseH;
  const pc = pcS ?? baseC;
  const pics = picS ?? basePics;
  const u = uS ?? baseU;
  const now = gm(b, pics, ph, pc, u);
  const base = gm(b, basePics, baseH, baseC, baseU);
  const curve = [];
  let maxClear = -1;
  for (let k = 0; k <= 8; k++) {
    const g = gm(b, k, ph, pc, u);
    if (g >= b.bar) maxClear = k;
    curve.push({ pics: k + ' pictures', gm: g, bar: b.bar });
  }
  const pct = (v) => (v * 100).toFixed(1) + '%';
  const reset = () => { setPh(null); setPc(null); setPic(null); setU(null); };
  return (
    <Col>
      <Text variant="heading">Gross margin at month 6: price and picture sensitivity</Text>
      <Text variant="soft">Mar 2027 customers from the saved model. Prices, usage and pictures are local what-ifs; nothing is written to the model. All cost inputs are estimates or assumptions.</Text>
      <Grid columns={3} minColumnWidth={180}>
        <Stat label="Gross margin, your settings" value={pct(now)} delta={(now >= base ? '+' : '') + ((now - base) * 100).toFixed(1) + ' pts vs saved plan'} positive={now >= base} />
        <Stat label={'Clears the ' + (b.bar * 100).toFixed(0) + '% bar'} value={now >= b.bar ? 'Yes' : 'No'} positive={now >= b.bar} />
        <Stat label="Most pictures per story that clear the bar" value={maxClear < 0 ? 'None' : String(maxClear)} />
      </Grid>
      <Grid columns={2} minColumnWidth={320}>
        <Col>
          <Slider label="Household price per month" value={ph} min={3} max={15} step={0.5} formatValue={(v) => '$' + Number(v).toFixed(2)} referenceValue={baseH} referenceLabel="Saved plan" onChange={setPh} onCommit={setPh} data-guide-anchor="household-price-slider" />
          <Slider label="Classroom price per month" value={pc} min={10} max={80} step={1} formatValue={(v) => '$' + Number(v).toFixed(0)} referenceValue={baseC} referenceLabel="Saved plan" onChange={setPc} onCommit={setPc} data-guide-anchor="classroom-price-slider" />
          <Slider label="Pictures per story" value={pics} min={0} max={8} step={1} formatValue={(v) => String(v)} referenceValue={basePics} referenceLabel="Saved plan" onChange={setPic} onCommit={setPic} data-guide-anchor="pictures-slider" />
          <Slider label="Stories used, share of included" value={u} min={0.2} max={1} step={0.05} formatValue={(v) => (Number(v) * 100).toFixed(0) + '%'} referenceValue={baseU} referenceLabel="Saved plan" onChange={setU} onCommit={setU} data-guide-anchor="usage-slider" />
          <Button onClick={reset}>Reset to saved plan</Button>
        </Col>
        <Chart
          height={300}
          options={{
            data: curve,
            series: [
              { type: 'line', xKey: 'pics', yKey: 'gm', yName: 'Gross margin' },
              { type: 'line', xKey: 'pics', yKey: 'bar', yName: 'Bar' },
            ],
            axes: [
              { type: 'category', position: 'bottom' },
              { type: 'number', position: 'left', label: { formatter: ({ value }) => (value * 100).toFixed(0) + '%' } },
            ],
          }}
        />
      </Grid>
    </Col>
  );
}

