const KEY = 'Ending cash (USD)';
const NCF = 'Net cash flow (USD)';
function usd(v) {
  return '$' + Math.round(v).toLocaleString('en-US');
}
function summarize(ds) {
  const rows = (ds && ds.rows) || [];
  const cash = rows.map((r) => Number(r[KEY]) || 0);
  const ncf = rows.map((r) => Number(r[NCF]) || 0);
  const minCash = cash.length ? Math.min(...cash) : 0;
  const minNcf = ncf.length ? Math.min(...ncf) : 0;
  const last = cash.length ? cash[cash.length - 1] : 0;
  let months = null;
  if (minNcf < 0) {
    const i = ncf.findIndex((v) => v < 0);
    months = i >= 0 && ncf[i] < 0 ? cash[i] / -ncf[i] : null;
  }
  return { minCash, minNcf, last, months };
}
function Block({ data }) {
  const bad = ['main', 'growth', 'downside'].find((k) => !data[k] || data[k].error);
  if (bad) return <Text variant="soft">Dataset {bad} is unavailable.</Text>;
  const m = data.main.rows || [];
  const g = data.growth.rows || [];
  const d = data.downside.rows || [];
  const merged = m.map((r, i) => ({
